<script setup>
import {ref,onMounted} from 'vue'
import {adminSections} from './admin-navigation.js'
import {call} from './pms-client.js'
import {adminEbook} from './admin-ebook.js'
const inquiry=ref(null),books=ref(null),inquiryError=ref(false),bookError=ref(false),busy=ref(false)
async function load(){if(busy.value)return;busy.value=true;await Promise.all([call('admin_inquiry_summary').then(v=>{inquiry.value=v;inquiryError.value=false}).catch(()=>{inquiry.value=null;inquiryError.value=true}),adminEbook('admin_summary').then(v=>{books.value=v;bookError.value=false}).catch(()=>{books.value=null;bookError.value=true})]);busy.value=false}
onMounted(load)
</script>
<template><main class="admin-overview"><header><span>PMOFFICE ADMIN</span><h1>시스템 관리</h1><p>회원 관리와 고객 지원, 서비스 운영 현황을 확인합니다.</p></header><section class="admin-summary" aria-label="처리 현황"><article><h2>고객 문의</h2><p v-if="inquiryError" role="alert">확인 실패 <button :disabled="busy" @click="load">다시 확인</button></p><p v-else-if="!inquiry" role="status">불러오는 중…</p><template v-else><a href="/admin/#client?status=신규">신규 <strong>{{inquiry.new}}</strong>건</a><a href="/admin/#client?status=확인%20중">확인 중 <strong>{{inquiry.processing}}</strong>건</a></template></article><article><h2>이북 처리</h2><p v-if="bookError" role="alert">확인 실패 <button :disabled="busy" @click="load">다시 확인</button></p><p v-else-if="!books" role="status">불러오는 중…</p><template v-else><a href="/admin/#ebooks?state=queued">변환 대기 <strong>{{books.queued}}</strong>건</a><a href="/admin/#ebooks?state=failed">변환 실패 <strong>{{books.failed}}</strong>건</a></template></article></section><section v-for="section in adminSections" :key="section.title" class="admin-home-section"><h2>{{section.title}}</h2><div class="admin-menu-cards"><a v-for="[key,label] in section.items" :key="key" :href="'/admin/#'+key"><strong>{{label}}</strong><span aria-hidden="true">→</span></a></div></section></main></template>
<style scoped>.admin-overview{padding:12px 10px 40px}.admin-overview h1{font-size:34px;font-weight:750;margin:10px 0}.admin-overview h2{font-size:20px;font-weight:700;margin:0 0 16px}.admin-overview header p{color:#596f85;margin:12px 0 28px}.admin-summary{display:grid;grid-template-columns:repeat(auto-fit,minmax(220px,1fr));gap:18px;margin-bottom:32px}.admin-summary article{background:#eef4fc;border:1px solid #d6e3f3;border-radius:12px;padding:22px}.admin-summary a{display:inline-block;margin:4px 22px 4px 0}.admin-summary strong{color:#1859a5;font-size:22px}.admin-home-section{margin:30px 0}.admin-menu-cards{display:grid;grid-template-columns:repeat(auto-fit,minmax(min(100%,280px),1fr));gap:14px}.admin-menu-cards a{display:flex;justify-content:space-between;gap:14px;border:1px solid #d5e0eb;border-radius:10px;padding:22px;background:white}.admin-menu-cards a:hover{border-color:#235fea;background:#f5f8fc}</style>
